tool_calls:
cd /home/eval/recon; mkdir -p out; tr -d '\r' < ledger.csv > /tmp/l.csv; tr -d '\r' < bank.tsv > /tmp/b.tsv
cat > /tmp/r.awk <<'EOF'
function milli(s,  neg,a,i,f){ gsub(/[ ,$]/,"",s); neg=0; if(s~/^-/){neg=1;s=substr(s,2)} else if(s~/^\+/)s=substr(s,2)
  i=index(s,"."); if(i){a=substr(s,1,i-1);f=substr(s,i+1)}else{a=s;f=""}
  f=substr(f "000",1,3); if(a=="")a=0; return (neg?-1:1)*(a*1000+f) }
function fmt(m,  neg,c){ neg=m<0; if(neg)m=-m; c=int(m/10); return sprintf("%s%d.%02d",neg?"-":"",int(c/100),c%100) }
function trim(s){gsub(/^[ \t]+|[ \t]+$/,"",s);return s}
function parsecsv(line,out,  n,i,c,q,f){ n=0;f="";q=0
  for(i=1;i<=length(line);i++){c=substr(line,i,1)
    if(q){ if(c=="\""){ if(substr(line,i+1,1)=="\""){f=f "\"";i++} else q=0 } else f=f c }
    else if(c=="\"")q=1; else if(c==","){out[++n]=f;f=""} else f=f c }
  out[++n]=f; return n }
FNR==1{next}
FILENAME==LF{ if($0=="")next; n=parsecsv($0,a); id=trim(a[1]); lr++; ld[id]=trim(a[2]); la[id]=milli(a[4]); lt+=la[id]; next }
{ if($0=="")next; split($0,a,"\t"); id=toupper(trim(a[1])); split(trim(a[2]),d,"/"); dt=sprintf("%04d-%02d-%02d",d[3],d[2],d[1]); am=milli(a[4])
  k=id SUBSEP dt SUBSEP am; if(k in seen){dup++;next} seen[k]=1; br++; bd[id]=dt; ba[id]=am; bt+=am }
END{ for(i in ld){ if(i in bd){ if(ld[i]==bd[i]&&la[i]==ba[i])m[++mc]=i; if(la[i]!=ba[i])am_[++ac]=i; if(ld[i]!=bd[i])dm[++dc]=i } else mb[++mbc]=i }
 for(i in bd) if(!(i in ld)) ml[++mlc]=i
 print "ledger_rows: " lr; print "bank_rows: " br; print "duplicate_bank_rows: " dup+0
 print "ledger_total: " fmt(lt); print "bank_total: " fmt(bt)
 print "matched: " mc+0
 print "amount_mismatch: " ac+0; for(j=1;j<=ac;j++)print "  " am_[j] " ledger=" fmt(la[am_[j]]) " bank=" fmt(ba[am_[j]])
 print "date_mismatch: " dc+0; for(j=1;j<=dc;j++)print "  " dm[j] " ledger=" ld[dm[j]] " bank=" bd[dm[j]]
 print "missing_in_bank: " mbc+0; for(j=1;j<=mbc;j++)print "  " mb[j]
 print "missing_in_ledger: " mlc+0; for(j=1;j<=mlc;j++)print "  " ml[j] }
EOF
# sorting: pipe each section's ids sorted via wrapper
awk -v LF=/tmp/l.csv -f /tmp/r.awk /tmp/l.csv /tmp/b.tsv | cat

